f-b369-5b05299816bd","option_text":"3ばん","is_correct":false,"sort_order":3}]},{"id":"70c2172a-0b5e-5876-94d7-2e830062bc7d","question":"いちばん いい へんじを えらんで ください。","question_type":"multiple_choice","question_category":"listening","section_number":15,"section_label":"即時応答","section_instruction":"音声を聞いて、いちばんいい返事をえらんでください。","passage":null,"audio_script":"A: あしたまでに 終わりそうですか。\nN: いちばん。\nB: あしたまで どこですか。\nN: にばん。\nB: 終わったら そうです。\nN: さんばん。\nB: あと 少しなので、大丈夫だと 思います。","image_url":null,"explanation":"あと少し memberikan dasar perkiraan selesai sebelum tenggat. Jawaban audio: “あと 少しなので、大丈夫だと 思います。”.","sort_order":86,"assessment_meta":{"version":"jlpt-final-n4-v1","form":"A","key":"n4-086","objective":"listening","itemType":"quick_response","source":"eznihongo-original","curriculumChapters":[3,11],"spokenChoices":["あしたまで どこですか。","終わったら そうです。","あと 少しなので、大丈夫だと 思います。"],"distractorReasons":["Pilihan “あしたまで どこですか。” tidak memenuhi petunjuk pada konteks. あと少し memberikan dasar perkiraan selesai sebelum tenggat.","Pilihan “終わったら そうです。” tidak memenuhi petunjuk pada konteks. あと少し memberikan dasar perkiraan selesai sebelum tenggat.","あと少し memberikan dasar perkiraan selesai sebelum tenggat."]},"options":[{"id":"0b2409d4-4f44-57c7-8a73-73b751e81feb","option_text":"1ばん","is_correct":false,"sort_order":1},{"id":"1db01ba6-d5d5-5037-b511-3648ec70a148","option_text":"2ばん","is_correct":false,"sort_order":2},{"id":"aed2350e-6ca9-581a-860e-8ffc9091c97c","option_text":"3ばん","is_correct":true,"sort_order":3}]},{"id":"f58ea2b3-6b72-5d67-beab-671833c50385","question":"いちばん いい へんじを えらんで ください。","question_type":"multiple_choice","question_category":"listening","section_number":15,"section_label":"即時応答","section_instruction":"音声を聞いて、いちばんいい返事をえらんでください。","passage":null,"audio_script":"A: その 本、読み終わったら 貸して もらえませんか。\nN: いちばん。\nB: いいですよ。借りて もらいます。\nN: にばん。\nB: いいですよ。読むなと 言いました。\nN: さんばん。\nB: いいですよ。来週 持って 来ますね。","image_url":null,"explanation":"Permintaan meminjam setelah selesai dibaca ditanggapi janji membawa buku. Jawaban audio: “いいですよ。来週 持って 来ますね。”.","sort_order":87,"assessment_meta":{"version":"jlpt-final-n4-v1","form":"A","key":"n4-087","objective":"listening","itemType":"quick_response","source":"eznihongo-original","curriculumChapters":[8,18],"spokenChoices":["いいですよ。借りて もらいます。","いいですよ。読むなと 言いました。","いいですよ。来週 持って 来ますね。"],"distractorReasons":["Pilihan “いいですよ。借りて もらいます。” tidak memenuhi petunjuk pada konteks. Permintaan meminjam setelah selesai dibaca ditanggapi janji membawa buku.","Pilihan “いいですよ。読むなと 言いました。” tidak memenuhi petunjuk pada konteks. Permintaan meminjam setelah selesai dibaca ditanggapi janji membawa buku.","Permintaan meminjam setelah selesai dibaca ditanggapi janji membawa buku."]},"options":[{"id":"584148cd-9994-5cba-9b4f-9d5267af486c","option_text":"1ばん","is_correct":false,"sort_order":1},{"id":"90ab9c12-dbf7-5c52-a737-b9ced54dccf4","option_text":"2ばん","is_correct":false,"sort_order":2},{"id":"0ac2605f-5be6-5403-add0-c404e0f89368","option_text":"3ばん","is_correct":true,"sort_order":3}]},{"id":"d80ddb22-c075-56cb-a1db-395960fc5edd","question":"いちばん いい へんじを えらんで ください。","question_type":"multiple_choice","question_category":"listening","section_number":15,"section_label":"即時応答","section_instruction":"音声を聞いて、いちばんいい返事をえらんでください。","passage":null,"audio_script":"A: 先生は もう お帰りに なりましたか。\nN: いちばん。\nB: いいえ、先生に 帰って まいりました。\nN: にばん。\nB: いいえ、先生を お帰りします。\nN: さんばん。\nB: いいえ、まだ 職員室に いらっしゃいます。","image_url":null,"explanation":"いらっしゃいます menyatakan keberadaan guru secara hormat. Jawaban audio: “いいえ、まだ 職員室に いらっしゃいます。”.","sort_order":88,"assessment_meta":{"version":"jlpt-final-n4-v1","form":"A","key":"n4-088","objective":"listening","itemType":"quick_response","source":"eznihongo-original","curriculumChapters":[23],"spokenChoices":["いいえ、先生に 帰って まいりました。","いいえ、先生を お帰りします。","いいえ、まだ 職員室に いらっしゃいます。"],"distractorReasons":["Pilihan “いいえ、先生に 帰って まいりました。” tidak memenuhi petunjuk pada konteks. いらっしゃいます menyatakan keberadaan guru secara hormat.","Pilihan “いいえ、先生を お帰りします。” tidak memenuhi petunjuk pada konteks. いらっしゃいます menyatakan keberadaan guru secara hormat.","いらっしゃいます menyatakan keberadaan guru secara hormat."]},"options":[{"id":"827a1895-4332-5a86-90c5-567f1ce03689","option_text":"1ばん","is_correct":false,"sort_order":1},{"id":"306c8a27-67f2-5752-9c8e-960e6b481764","option_text":"2ばん","is_correct":false,"sort_order":2},{"id":"2575d1c6-1f45-5958-856f-377b2c541bda","option_text":"3ばん","is_correct":true,"sort_order":3}]},{"id":"0f9cf527-1667-5c48-b0a0-003b6b66d660","question":"いちばん いい へんじを えらんで ください。","question_type":"multiple_choice","question_category":"listening","section_number":15,"section_label":"即時応答","section_instruction":"音声を聞いて、いちばんいい返事をえらんでください。","passage":null,"audio_script":"A: どうしたんですか。元気が ありませんね。\nN: いちばん。\nB: はい、元気が ありませんか。\nN: にばん。\nB: きのう 眠らせて ください。\nN: さんばん。\nB: きのう あまり 眠れなかったんです。","image_url":null,"explanation":"Pertanyaan meminta penjelasan keadaan, dijawab alasan kurang tidur. Jawaban audio: “きのう あまり 眠れなかったんです。”.","sort_order":89,"assessment_meta":{"version":"jlpt-final-n4-v1","form":"A","key":"n4-089","objective":"listening","itemType":"quick_response","source":"eznihongo-original","curriculumChapters":[2,4],"spokenChoices":["はい、元気が ありませんか。","きのう 眠らせて ください。","きのう あまり 眠れなかったんです。"],"distractorReasons":["Pilihan “はい、元気が ありませんか。” tidak memenuhi petunjuk pada konteks. Pertanyaan meminta penjelasan keadaan, dijawab alasan kurang tidur.","Pilihan “きのう 眠らせて ください。” tidak memenuhi petunjuk pada konteks. Pertanyaan meminta penjelasan keadaan, dijawab alasan kurang tidur.","Pertanyaan meminta penjelasan keadaan, dijawab alasan kurang tidur."]},"options":[{"id":"67dc5ab5-b9ce-5f9a-bbfb-19cd07ebeb57","option_text":"1ばん","is_correct":false,"sort_order":1},{"id":"fbdd37c1-f59a-5e17-b1c8-cd78a0189418","option_text":"2ばん","is_correct":false,"sort_order":2},{"id":"d948c647-c7b3-55f7-86d3-3c590bdd5f21","option_text":"3ばん","is_correct":true,"sort_order":3}]},{"id":"c51b419d-52d0-5cdb-b372-427e3a23732f","question":"いちばん いい へんじを えらんで ください。","question_type":"multiple_choice","question_category":"listening","section_number":15,"section_label":"即時応答","section_instruction":"音声を聞いて、いちばんいい返事をえらんでください。","passage":null,"audio_script":"A: 荷物を ここに 置いたままで いいですか。\nN: いちばん。\nB: はい、わたしが 置いて ください。\nN: にばん。\nB: はい、わたしが 見て いますから。\nN: さんばん。\nB: はい、もう 置きませんでした。","image_url":null,"explanation":"Izin membiarkan barang dijawab dengan jaminan menjaganya. Jawaban audio: “はい、わたしが 見て いますから。”.","sort_order":90,"assessment_meta":{"version":"jlpt-final-n4-v1","form":"A","key":"n4-090","objective":"listening","itemType":"quick_response","source":"eznihongo-original","curriculumChapters":[20],"spokenChoices":["はい、わたしが 置いて ください。","はい、わたしが 見て いますから。","はい、もう 置きませんでした。"],"distractorReasons":["Pilihan “はい、わたしが 置いて ください。” tidak memenuhi petunjuk pada konteks. Izin membiarkan barang dijawab dengan jaminan menjaganya.","Izin membiarkan barang dijawab dengan jaminan menjaganya.","Pilihan “はい、もう 置きませんでした。” tidak memenuhi petunjuk pada konteks. Izin membiarkan barang dijawab dengan jaminan menjaganya."]},"options":[{"id":"63adc435-c7ca-50b4-a54a-50a81b698faf","option_text":"1ばん","is_correct":false,"sort_order":1},{"id":"25f2bfc2-ce9b-55ad-80e3-ab368ba63f55","option_text":"2ばん","is_correct":true,"sort_order":2},{"id":"14eaf93f-ced0-51bb-9472-40a8c044e3fa","option_text":"3ばん","is_correct":false,"sort_order":3}]}]}]$bank$::jsonb;
 b jsonb; q jsonb; o jsonb; course_uuid uuid; module_order int; existing_count int;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('curriculum-boundary:graph'));
 LOCK TABLE courses,modules,lessons,quiz_questions,quiz_options IN SHARE ROW EXCLUSIVE MODE;
 -- Preflight both courses before writing either bank.
 FOR b IN SELECT value FROM jsonb_array_elements(payload) LOOP
  SELECT count(*) INTO existing_count FROM courses WHERE slug=b->>'level';
  IF existing_count<>1 THEN RAISE EXCEPTION '194 missing/ambiguous course: %',b->>'level'; END IF;
  IF EXISTS(SELECT 1 FROM modules m JOIN courses c ON c.id=m.course_id WHERE c.slug=b->>'level' AND m.slug=b->>'moduleSlug' AND m.id<>(b->>'moduleId')::uuid)
   THEN RAISE EXCEPTION '194 final module slug already used: %',b->>'level'; END IF;
  IF EXISTS(SELECT 1 FROM lessons WHERE id=(b->>'lessonId')::uuid) THEN
   IF NOT EXISTS(SELECT 1 FROM lessons l JOIN modules m ON m.id=l.module_id JOIN courses c ON c.id=m.course_id
     WHERE l.id=(b->>'lessonId')::uuid AND l.slug=b->>'lessonSlug' AND l.type='quiz'
       AND m.id=(b->>'moduleId')::uuid AND m.slug=b->>'moduleSlug' AND c.slug=b->>'level'
       AND l.assessment_policy->>'version'=b->>'version')
    THEN RAISE EXCEPTION '194 conflicting final exam: %',b->>'level'; END IF;
   SELECT count(*) INTO existing_count FROM quiz_questions WHERE lesson_id=(b->>'lessonId')::uuid AND assessment_meta->>'version'=b->>'version';
   IF existing_count<>jsonb_array_length(b->'rows') THEN RAISE EXCEPTION '194 incomplete existing bank'; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(b->'rows') x WHERE NOT EXISTS(SELECT 1 FROM quiz_questions q WHERE q.id=(x->>'id')::uuid AND q.lesson_id=(b->>'lessonId')::uuid))
    THEN RAISE EXCEPTION '194 existing question identity changed'; END IF;
  ELSIF EXISTS(SELECT 1 FROM modules WHERE id=(b->>'moduleId')::uuid) THEN
   RAISE EXCEPTION '194 conflicting module identity';
  END IF;
 END LOOP;
 FOR b IN SELECT value FROM jsonb_array_elements(payload) LOOP
  -- Preserve later teacher edits on replay rather than overwriting their bank.
  IF EXISTS(SELECT 1 FROM lessons WHERE id=(b->>'lessonId')::uuid) THEN CONTINUE; END IF;
  SELECT id INTO course_uuid FROM courses WHERE slug=b->>'level';
  PERFORM pg_advisory_xact_lock(hashtext('curriculum-boundary:'||course_uuid::text));
  SELECT coalesce(max(sort_order),0)+1 INTO module_order FROM modules WHERE course_id=course_uuid;
  INSERT INTO modules(id,course_id,slug,title,description,sort_order,section_name,quiz_spec)
   VALUES((b->>'moduleId')::uuid,course_uuid,b->>'moduleSlug',b->>'title',b->>'content',module_order,'Final Exam',jsonb_build_object('total',jsonb_array_length(b->'rows'),'version',b->>'version'));
  INSERT INTO lessons(id,module_id,slug,title,type,content,sort_order,passing_score_pct,questions_per_attempt,assessment_policy,cooldown_hours)
   VALUES((b->>'lessonId')::uuid,(b->>'moduleId')::uuid,b->>'lessonSlug',b->>'title','quiz',b->>'content',1,70,jsonb_array_length(b->'rows'),b->'policy',12);
  FOR q IN SELECT value FROM jsonb_array_elements(b->'rows') LOOP
   INSERT INTO quiz_questions(id,lesson_id,question,question_type,question_category,section_number,section_label,section_instruction,passage,audio_script,image_url,explanation,sort_order,assessment_meta)
    VALUES((q->>'id')::uuid,(b->>'lessonId')::uuid,q->>'question',q->>'question_type',q->>'question_category',(q->>'section_number')::int,q->>'section_label',q->>'section_instruction',q->>'passage',q->>'audio_script',q->>'image_url',q->>'explanation',(q->>'sort_order')::int,q->'assessment_meta');
   FOR o IN SELECT value FROM jsonb_array_elements(q->'options') LOOP
    INSERT INTO quiz_options(id,question_id,option_text,is_correct,sort_order)
     VALUES((o->>'id')::uuid,(q->>'id')::uuid,o->>'option_text',(o->>'is_correct')::boolean,(o->>'sort_order')::int);
   END LOOP;
  END LOOP;
 END LOOP;
END $final$;
